// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CLEToken {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xDeEa8fdB85503531F6A5D2A036d3268bD7C06c09;
    address attacker;
    CLEToken token;
    address currentOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        token = CLEToken(TARGET);
        currentOwner = token.owner();
        vm.label(currentOwner, "Current Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Impersonate the current owner
        vm.startPrank(currentOwner);

        // Step 2: Transfer ownership to attacker
        token.transferOwnership(attacker);

        // Step 3: Stop impersonation
        vm.stopPrank();

        // Step 4: Verify the attacker is now the owner (oracle check)
        assertEq(token.owner(), attacker, "Attacker should be the new owner");
        assertEq(token.owner(), attacker, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
